E.code.oninput=()=>{state.dirty=true;E.codeState.textContent="changed";E.playBtn.disabled=true;updateGutter()};E.code.onscroll=()=>E.gutter.scrollTop=E.code.scrollTop;E.code.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==="Enter"){e.preventDefault();run()}if(e.key==="Tab"){e.preventDefault();E.code.setRangeText("    ",E.code.selectionStart,E.code.selectionEnd,"end")}};
function expandAll(){if(mobile()){showMobile("code");return}[E.sourcePane,E.codePane,E.soundPane].forEach(p=>p.classList.remove("min"));document.querySelectorAll(".minBtn").forEach(b=>b.textContent="−");setWidths()}
function setWidths(){if(mobile())return;const P=[E.sourcePane,E.codePane,E.soundPane],vis=P.map(p=>!p.classList.contains("min")),sum=state.widths.reduce((a,x,i)=>a+(vis[i]?x:0),0)||1;P.forEach((p,i)=>p.style.flex=vis[i]?`0 0 ${state.widths[i]/sum*100}%`:"0 0 34px");document.querySelectorAll(".grip").forEach((g,i)=>g.hidden=!(vis[i]&&vis[i+1]))}
document.querySelectorAll("[data-min]").forEach(b=>b.onclick=()=>{if(mobile())return;const p={source:E.sourcePane,code:E.codePane,sound:E.soundPane}[b.dataset.min];p.classList.toggle("min");b.textContent=p.classList.contains("min")?"+":"−";setWidths()});
document.querySelectorAll("[data-mobile]").forEach(b=>b.onclick=()=>{if(!b.disabled)showMobile(b.dataset.mobile)});function showMobile(name){if(!mobile())return;document.querySelectorAll(".pane").forEach(p=>p.classList.toggle("mobileOn",p.dataset.pane===name));document.querySelectorAll("[data-mobile]").forEach(b=>b.classList.toggle("on",b.dataset.mobile===name));if(name==="source")setTimeout(fitSketch,0);if(name==="sound")setTimeout(drawSpec,0)}
