/* prompt/completion ledger + multi-track invariant editing */
const LOG_KEY="es.promptlog.v1";
state.selectedTracks=new Set();state.anchorTracks=new Set();
const X={groupBtn:$("groupBtn"),anchorBtn:$("anchorBtn"),fitOthersBtn:$("fitOthersBtn"),selectionClear:$("selectionClear"),logBtn:$("logBtn"),logBack:$("logBack"),logList:$("logList"),logMeta:$("logMeta"),logExport:$("logExport"),logClear:$("logClear"),logClose:$("logClose")};
function logRows(){try{const a=JSON.parse(localStorage.getItem(LOG_KEY)||"[]");return Array.isArray(a)?a:[]}catch(_){return[]}}
function writeLog(a){try{localStorage.setItem(LOG_KEY,JSON.stringify(a.slice(-80)))}catch(_){}}
function recordPair(entry){const row={id:`p_${Date.now().toString(36)}_${Math.floor(Math.random()*1e6).toString(36)}`,at:new Date().toISOString(),model:state.model,...entry},a=logRows();a.push(row);writeLog(a);const s=current();if(s){s.promptLogIds=[...(s.promptLogIds||[]),row.id]}renderLog();return row}
function previewCompletion(c){if(!c)return"";if(c.summary)return c.summary;if(Array.isArray(c.stones))return c.stones.map(x=>`${x.name} / ${x.genre}`).join(" · ");if(Array.isArray(c.patches))return c.patches.map(x=>`T${x.track}`).join(" + ")+" patched";return JSON.stringify(c).slice(0,140)}
function renderLog(){if(!X.logList)return;const a=logRows();X.logMeta.textContent=`${a.length} pairs`;X.logList.innerHTML="";if(!a.length){X.logList.innerHTML='<div class="logEmpty">No prompts yet.</div>';return}for(const r of [...a].reverse()){const d=document.createElement("div");d.className="logItem";const when=document.createElement("div");when.className="logWhen";const dt=new Date(r.at);when.textContent=`${dt.toLocaleDateString()}\n${dt.toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`;const pair=document.createElement("div");pair.className="logPair";const targets=r.targets?.length?` · ${r.targets.map(x=>`T${x}`).join("+")}`:"";pair.innerHTML=`<b>${esc(String(r.scope||"PROMPT").toUpperCase()+targets)}</b><div class="p">${esc(r.prompt||"(drawing only)")}</div><div class="c">→ ${esc(previewCompletion(r.completion))}</div>`;d.append(when,pair);X.logList.appendChild(d)}}
X.logBtn.onclick=()=>{renderLog();X.logBack.classList.add("open")};X.logClose.onclick=()=>X.logBack.classList.remove("open");X.logBack.onclick=e=>{if(e.target===X.logBack)X.logBack.classList.remove("open")};
X.logExport.onclick=()=>{const rows=logRows(),txt=rows.map(x=>JSON.stringify(x)).join("\n");downloadBlob(new Blob([txt],{type:"application/x-ndjson"}),`es-prompt-log-${new Date().toISOString().slice(0,10)}.jsonl`);setTrace("LOG",`${rows.length} prompt/completion pairs`,"downloaded")};
X.logClear.onclick=()=>{if(confirm("Clear the prompt/completion log on this browser?")){localStorage.removeItem(LOG_KEY);renderLog();setTrace("LOG","cleared","kept songs unchanged")}};

/* record whole-song MAKE pairs */
const makeBase=make;make=async function(){const before=state.stones.map(s=>s.id).join("|"),prompt=E.prompt.value.trim(),draw=structuredClone(drawingDNA()),sourceAtStart=E.prompt.value;await makeBase();const after=state.stones.map(s=>s.id).join("|");if(after&&after!==before){const compact=state.stones.map(s=>({id:s.id,name:s.name,genre:s.genre,lineage:s.lineage,hook:s.hook,tempo:s.tempo,key:s.key,mode:s.mode,groove:s.groove,palette:s.palette,progression:s.progression,bassMotif:s.bassMotif,leadMotif:s.leadMotif,density:s.density,drawingUse:s.drawingUse,surprise:s.surprise})),row=recordPair({scope:"song",prompt:prompt||"(drawing only)",source:sourceAtStart,drawing:draw,completion:{stones:compact}});for(const s of state.stones)s.promptLogIds=[...(s.promptLogIds||[]),row.id]}};E.makeBtn.onclick=make;

function allTracks(){return state.ir?[...new Set(state.ir.events.map(e=>e.track))].sort((a,b)=>a-b):[]}
function selectedArray(){return [...state.selectedTracks].sort((a,b)=>a-b)}
function editableSelected(){const a=selectedArray().filter(t=>!state.anchorTracks.has(t));if(a.length)return a;if(state.selectedTrack!=null&&!state.anchorTracks.has(state.selectedTrack))return[state.selectedTrack];return[]}
function updateSelectionUI(){const sel=selectedArray();if(X.groupBtn){X.groupBtn.hidden=!sel.length;X.groupBtn.textContent=`EDIT ${sel.length}`}for(const row of document.querySelectorAll(".track")){const lab=row.querySelector(".tlabel"),tr=Number(lab?.textContent);row.classList.toggle("selected",state.selectedTracks.has(tr));row.classList.toggle("anchor",state.anchorTracks.has(tr));lab?.classList.toggle("selected",state.selectedTracks.has(tr));lab?.classList.toggle("anchor",state.anchorTracks.has(tr))}if(X.anchorBtn){const all=sel.length&&sel.every(t=>state.anchorTracks.has(t));X.anchorBtn.classList.toggle("on",!!all);X.anchorBtn.textContent=all?"UNLOCK":"INVARIANT"}}
function toggleTrack(tr){if(state.selectedTracks.has(tr))state.selectedTracks.delete(tr);else state.selectedTracks.add(tr);state.selectedTrack=tr;updateSelectionUI()}
function openSelectionSheet(focusTrack=null){if(focusTrack!=null){state.selectedTrack=focusTrack;if(!state.selectedTracks.size)state.selectedTracks.add(focusTrack)}const sel=selectedArray(),anchors=[...state.anchorTracks].sort((a,b)=>a-b);E.trackTitle.textContent=sel.length>1?`${sel.length} TRACKS`:sel.length?`${sel[0]} · ${trackName(sel[0])}`:"TRACKS";E.trackMeta.textContent=anchors.length?`invariant ${anchors.map(x=>`T${x}`).join(" ")}`:`${sel.length} selected`;E.trackPrompt.placeholder=sel.length>1?"Reprompt these tracks together…":"Change this track…";E.trackAI.textContent=sel.length>1?`TUNE ${sel.length}`:"TUNE";E.trackReadout.textContent=sel.length?`selected ${sel.map(x=>`T${x} ${trackName(x)}`).join(" · ")}`:"tap track numbers to select";E.trackBack.classList.add("open");updateSelectionUI()}
X.groupBtn.onclick=()=>openSelectionSheet();
const openTrackBase=openTrack;openTrack=function(tr){state.selectedTrack=tr;if(!state.selectedTracks.has(tr)){if(!state.selectedTracks.size)state.selectedTracks.add(tr)}openSelectionSheet(tr)};
const renderTimelineBase=renderTimeline;renderTimeline=function(){renderTimelineBase();for(const row of document.querySelectorAll(".track")){const lab=row.querySelector(".tlabel"),tr=Number(lab?.textContent);if(!Number.isFinite(tr))continue;let sx=0,moved=false;lab.onclick=null;lab.onpointerdown=ev=>{sx=ev.clientX;moved=false;lab.setPointerCapture?.(ev.pointerId)};lab.onpointermove=ev=>{if(Math.abs(ev.clientX-sx)>14)moved=true};lab.onpointerup=ev=>{const dx=ev.clientX-sx;if(Math.abs(dx)>18){const beat=Math.round(dx/45*4)/4;applyPatchBatch([{track:tr,shift:(trackPatch(tr).shift||0)+beat}]).catch(()=>{})}else if(!moved)toggleTrack(tr)};}updateSelectionUI()};

X.anchorBtn.onclick=()=>{const sel=selectedArray();if(!sel.length)return;const all=sel.every(t=>state.anchorTracks.has(t));for(const t of sel){if(all)state.anchorTracks.delete(t);else state.anchorTracks.add(t)}const s=current();if(s)s.anchors=[...state.anchorTracks];updateSelectionUI();openSelectionSheet();setTrace(all?"INVARIANT RELEASED":"INVARIANT",sel.map(x=>`T${x}`).join(" + "),all?"editable again":"will not change during fit")};
X.selectionClear.onclick=()=>{state.selectedTracks.clear();state.selectedTrack=null;updateSelectionUI();E.trackBack.classList.remove("open")};

function patchLine(lines,tr,patch){const re=new RegExp(`^\\s*track\\(\\s*${tr}\\s*,`),idx=lines.findIndex(x=>re.test(x));let old={};if(idx>=0){try{old=parseVal(splitArgs(lines[idx].match(/^\s*track\((.*)\)\s*$/)[1])[1])||{}}catch(_){old={}}}const merged={...old,...patch};if(merged.delete===false)delete merged.delete;if(merged.mute===false)delete merged.mute;if(merged.query==="")delete merged.query;if(merged.behavior==="")delete merged.behavior;const line=`track(${tr}, ${JSON.stringify(merged)})`;if(idx>=0)lines[idx]=line;else lines.push(line)}
async function applyPatchBatch(patches){const lines=E.code.value.split("\n");for(const x of patches){const tr=Math.round(+x.track);if(!Number.isFinite(tr)||state.anchorTracks.has(tr))continue;const p={...x};delete p.track;patchLine(lines,tr,p)}E.code.value=lines.join("\n");E.codeState.textContent="changed";state.dirty=true;updateGutter();await run();updateSelectionUI()}
function nextSwap(tr){const idx=tr-7,p=state.plan?.palette?.[idx];if(!p||!state.catalog?.length)return null;const cur=state.plan?.trackPatches?.[String(tr)]?.soundName||p.sound?.name||"",s=resolveSound(p.role,state.plan?.trackPatches?.[String(tr)]?.query||p.query,state.plan.genre,cur);return s?.name||null}
document.querySelectorAll("[data-track-op]").forEach(b=>b.onclick=async()=>{const targets=editableSelected();if(!targets.length){E.trackReadout.textContent="selected tracks are invariant";return}const op=b.dataset.trackOp,patches=[];let copyBase=Math.max(...allTracks(),20)+1;for(const tr of targets){const p=trackPatch(tr),x={track:tr};if(op==="left")x.shift=(+p.shift||0)-.25;if(op==="right")x.shift=(+p.shift||0)+.25;if(op==="down")x.transpose=(+p.transpose||0)-1;if(op==="up")x.transpose=(+p.transpose||0)+1;if(op==="octdown")x.transpose=(+p.transpose||0)-12;if(op==="octup")x.transpose=(+p.transpose||0)+12;if(op==="mute")x.mute=!p.mute;if(op==="delete")x.delete=true;if(op==="copy"){x.copyTo=copyBase++;x.copyShift=0;x.copyTranspose=0}if(op==="swap"){const n=nextSwap(tr);if(n)x.soundName=n}patches.push(x)}await applyPatchBatch(patches);openSelectionSheet()});

function multiPatchSchema(){return{type:"object",additionalProperties:false,required:["summary","patches"],properties:{summary:{type:"string",maxLength:140},patches:{type:"array",minItems:1,maxItems:24,items:{type:"object",additionalProperties:false,required:["track","shift","transpose","gain","mute","delete","query","behavior"],properties:{track:{type:"integer",minimum:1,maximum:64},shift:{type:"number",minimum:-16,maximum:16},transpose:{type:"integer",minimum:-24,maximum:24},gain:{type:"number",minimum:.05,maximum:1.5},mute:{type:"boolean"},delete:{type:"boolean"},query:{type:"string",maxLength:60},behavior:{type:"string",enum:["","loop","one_shot","chop","punctuate"]}}}}}}}
function trackContext(tr){return{track:tr,name:trackName(tr),patch:trackPatch(tr),events:(state.ir?.events||[]).filter(e=>e.track===tr).slice(0,24).map(e=>({type:e.type,start:+e.start.toFixed(3),dur:+e.dur.toFixed(3),note:e.note,vel:+e.vel.toFixed(2),role:e.role,query:e.query,sound:e.sound?.name}))}}
async function tuneTracks(targets,request,scope="tracks"){targets=[...new Set(targets.map(Number))].filter(t=>Number.isFinite(t)&&!state.anchorTracks.has(t));if(!targets.length){E.trackReadout.textContent="no editable target tracks";return}if(!state.connected){showSheet();return}const anchors=[...state.anchorTracks].filter(t=>allTracks().includes(t)),prompt=request.trim()||"Make these tracks cohere more strongly as an ensemble while preserving their distinctive roles.";E.trackAI.disabled=true;E.trackReadout.textContent=`tuning ${targets.map(x=>`T${x}`).join(" + ")}…`;try{const d=await apiFetch("/responses",{method:"POST",body:JSON.stringify({model:state.model,instructions:"You are editing a multitrack musical arrangement. Tracks listed as INVARIANTS are immutable evidence: do not return patches for them. Modify only TARGET tracks. Coordinate target changes with one another and with the invariant tracks so timing, register, density, timbre and source material hang together. Return small deterministic patches, not a whole new song.",input:[{role:"user",content:[{type:"input_text",text:`SONG ${state.plan?.genre||""} | ${state.plan?.tempo||""} bpm | ${state.plan?.key||""} ${state.plan?.mode||""}\nREQUEST: ${prompt}\nINVARIANTS: ${JSON.stringify(anchors.map(trackContext))}\nTARGETS: ${JSON.stringify(targets.map(trackContext))}\nOTHER TRACKS (context only): ${JSON.stringify(allTracks().filter(t=>!targets.includes(t)&&!anchors.includes(t)).map(trackContext))}`}]}],text:{format:{type:"json_schema",name:"multi_track_patch",strict:true,schema:multiPatchSchema()}}})}),completion=JSON.parse(outputText(d)),valid=completion.patches.filter(x=>targets.includes(Number(x.track))&&!state.anchorTracks.has(Number(x.track)));await applyPatchBatch(valid);const row=recordPair({scope,prompt,targets,anchors,stoneId:current()?.id,completion:{summary:completion.summary,patches:valid}});const s=current();if(s)s.promptLogIds=[...(s.promptLogIds||[]),row.id];E.trackReadout.textContent=completion.summary;E.trackPrompt.value="";openSelectionSheet()}catch(e){E.trackReadout.textContent=e.message;setTrace("FAULT","track prompt preserved",e.message)}finally{E.trackAI.disabled=false}}
E.trackAI.onclick=()=>tuneTracks(editableSelected(),E.trackPrompt.value,"tracks");
X.fitOthersBtn.onclick=()=>{const anchors=[...state.anchorTracks];if(!anchors.length){E.trackReadout.textContent="select a track, mark INVARIANT, then FIT OTHERS";return}const targets=allTracks().filter(t=>!state.anchorTracks.has(t));const ask=E.trackPrompt.value.trim()||"Rework every non-invariant track so the arrangement fits the invariant track(s) naturally. Preserve the invariant exactly. Make supporting parts share a coherent pocket, register hierarchy and material world without making them identical.";state.selectedTracks=new Set(targets);updateSelectionUI();tuneTracks(targets,ask,"fit-to-invariant")};

/* KEEP and PROJECT now carry anchors + prompt references */
const saveCurrentBase=saveCurrent;saveCurrent=function(){const s=current();if(s){s.anchors=[...state.anchorTracks];s.promptLogIds=s.promptLogIds||[]}saveCurrentBase()};E.keepBtn.onclick=saveCurrent;
const loadStoneBase=loadStone;loadStone=async function(s){await loadStoneBase(s);state.anchorTracks=new Set((s?.anchors||[]).map(Number));state.selectedTracks.clear();state.selectedTrack=null;updateSelectionUI()};
E.projectExport.onclick=()=>{const s=current();if(!s)return;const ids=new Set(s.promptLogIds||[]),related=logRows().filter(x=>ids.has(x.id)||x.stoneId===s.id),project={version:2,savedAt:new Date().toISOString(),source:E.prompt.value,strokes:state.strokes,stone:{...s,anchors:[...state.anchorTracks]},code:E.code.value,plan:state.plan,invariants:[...state.anchorTracks],promptCompletionLog:related};downloadBlob(new Blob([JSON.stringify(project,null,2)],{type:"application/json"}),`${s.name||"es"}.es-project.json`);setTrace("EXPORT","PROJECT",`${related.length} prompt pairs included`)};

